#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

void init_gpio(void);
void init_tim3(void);


int main(void){

    // Configurar el hardware del microcontrolador antes de entrar al bucle infinito (funcion principal)
    init_gpio(); // Inicializar el GPIOA, especificamente el pin PA5 como salida push-pull
    init_tim3(); // Inicializar el TIM3 para que genere una interrupcion cada 2.5 segundos

    /* Loop forever */
	while(1){

    }

    return 0;
}

void init_gpio(void){
    // Encender la senal de reloj para el GPIOA
    //RCC->AHB1ENR |=  (1<<0); // Habilitar el reloj para GPIOA, es la forma manual de hacerlo, pero es mejor usar la macro definida en el archivo stm32f411xe.h
    RCC->AHB1ENR |= RCC_AHB1ENR_GPIOAEN_Msk; // Habilitar el reloj para GPIOA


    // Configurar el pin PA5 como salida push_pull
    GPIOA->MODER &= ~(0b11 << GPIO_MODER_MODE5_Pos); // Limpiar los bits de modo del pin PA5
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODE5_Pos); // Configurar el pin PA5 como salida

    // Configurar el pin PA5 como push-pull
    GPIOA->OTYPER &= ~(GPIO_OTYPER_OT5); // Limpiar la posicion 5, configuramos como salida push-pull

    // Configuramos la velocidad del pin PA5
    GPIOA->OSPEEDR |= ~(0b11 << GPIO_OSPEEDR_OSPEED5_Pos); // Limpiar los bits de velocidad del pin PA5
    GPIOA->OSPEEDR |= (0b01 << GPIO_OSPEEDR_OSPEED5_Pos); // Configurar la velocidad del pin PA5 como velocidad media por eso el valor 01 (0b01=1)

    GPIOA->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD5_Pos); // Limpiar los bits de pull-up/pull-down del pin PA5, deshabilitamos el pull-up y pull-down

    GPIOA->ODR |= (GPIO_ODR_OD5); // Encender el pin PA5, es decir, encender el LED verde del Nucleo F411RE
}


void init_tim3(void){

    // Encender la senal de reloj para el TIM3
    RCC->APB1ENR |= RCC_APB1ENR_TIM3EN; // Encencemos la senal de reloj para el TIM3

    // Configuracion del TIM3, lo podemos ver en la seccion 13.1.1 del Reference Manual RM0383, y en la seccion 15.3.1 del datasheet del STM32F411RE
    TIM3->CNT = 0; // Inicializamos el contador del TIM3 en 0
    TIM3->PSC = (1600 - 1); // Configuramos el prescaler del TIM3 para que cuente a 1 kHz (16 MHz / 16000 = 1 kHz, 0.1us), y la resta de 1 es porque el prescaler cuenta desde 0, entonces si queremos que cuente hasta 16000, debemos poner 15999
    TIM3->ARR = (2500 -1); // Configuramos el auto-reload del TIM3 para que cuente hasta 2500, es decir, 2.5 segundos (1 kHz / 2500 = 0.4 Hz, 2.5 segundos), y la resta de 1 es porque el auto-reload cuenta desde 0, entonces si queremos que cuente hasta 2500, debemos poner 2499

    TIM3->CR1 &= ~(0b11 << TIM_CR1_CKD_Pos); // Limpiamos los bits de clock division del TIM3, para que cuente a la frecuencia del prescaler (1 kHz)
    TIM3->CR1 |= (TIM_CR1_ARPE); // Configuramos el TIM3 para que actualice el auto-reload en cada overflow del contador
    TIM3->CR1 |= (TIM_CR1_DIR_Pos); // Configuramos el TIM3 para que cuente hacia arriba (upcounting mode)

    TIM3->DIER |= (TIM_DIER_UIE); // Habilitamos la interrupcion de update del TIM3, para que se genere una interrupcion cada vez que el contador llegue al auto-reload

    /*Ahora vamos a registrar la interrupcion en el NVIC*/
    NVIC_EnableIRQ(TIM3_IRQn); // Habilitamos la interrupcion del TIM3 en el NVIC, para que se pueda generar la interrupcion cuando el contador llegue al auto-reload
   

    // Activamos el contador - to-do esto lo podemos ver en la seccion 13.3.1 del Reference Manual RM0383, y en la seccion 15.3.1 del datasheet del STM32F411RE
    TIM3->CR1 |= (TIM_CR1_CEN); // Activamos el contador, permitir que se incremente el contador del TIM3, es decir, que empiece a contar desde 0 hasta el auto-reload (2500), y cuando llegue al auto-reload, se genere una interrupcion y se reinicie el contador a 0
}

/* Ahora vamos a implementar la funcion de manejo de interrupcion del TIM3, que se puede revisar en el archivo "startup_stm32f411xe.s", esta funcion 
TIM3_IRQHandler() ya esta creada, por eso no es necesario crearla, solo debemos implementarla, que es sobreescribiendo el metodo. Esta funcion se ejecutara cada vez que el TIM3 genere una interrupcion, es decir, cada vez que el contador llegue al auto-reload (2500), es decir, cada 2.5 segundos. En esta funcion vamos a hacer un toggle del pin PA5, es decir, vamos a encender y apagar el LED verde del Nucleo F411RE cada 2.5 segundos.
*/
void TIM3_IRQHandler(void){
    
    // Primero debemos verificar que la "bandera" esta en alto, es to es si la interrupcion fue generada por el update del TIM3, es decir, si el contador llego al auto-reload
    if(TIM3->SR && TIM_SR_UIF) // El TIM_SR_UIF es la bandera el cual tendria valor de 1, y con el operador && (comparacion entre 2 valores numericos) respecto a TIM3->SR, si el resultado es 1, entonces la bandera esta en alto, es decir, la interrupcion fue generada por el update del TIM3
    {
        TIM3->SR &= ~(TIM_SR_UIF); // Limpiamos la bandera de update del TIM3, es decir bajamos la bandera, para que no se genere otra interrupcion hasta que el contador llegue al auto-reload nuevamente

        // Hacemos "algo" en la interupcion, en este caso vamos a hacer un toggle del pin PA5, es decir, vamos a encender y apagar el LED verde del Nucleo F411RE cada 2.5 segundos.
        GPIOA->ODR ^= (GPIO_ODR_OD5); // Hacemos un toggle del pin PA5 (posicion 5), es decir, encendemos y apagamos el LED verde del Nucleo F411RE cada 2.5 segundos. El ^ es el operador XOR, que hace un toggle del bit correspondiente al pin PA5 en el registro ODR (Output Data Register) del GPIOA. Si el bit esta en 1, lo pone en 0, y si esta en 0, lo pone en 1.
      
    } 

}